INSERT INTO employer_extractions (employer_id, name, source_period, women_employees_pct, women_management_pct, women_board_pct, lifeatwork_women_family_winner, lifeatwork_other_dei_winner, lifeatwork_finalist_or_entrant, flexworklife_fwa_adopter, other_gov_family_recognition, maternity_days, flexible_or_remote, childcare_nursing_phased_return, paternity_beyond_statutory, policy_score_basis, management_definition, source_scope, period_consistency, extraction_notes) VALUES
    ('emp-my-plc-02488', 'Alliance Bank Malaysia Berhad', 'FY2024', 62, 21, 30, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, 'known_positive_signals_only', 'management', 'Alliance Bank group', 'single_period', 'Flexible/hybrid/staggered arrangements are disclosed. Leave described without enough day-level detail for D7 maternity/paternity points.'),
    ('emp-my-plc-01015', 'AMMB Holdings Berhad', 'FY2024', 61.94, 43.2, 33, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, 'known_positive_signals_only', 'senior management', 'AmBank Group', 'single_period', 'Women employees calculated from disclosed counts: 4,766 of 7,695. Flexible work is evidenced; other policy fields remain null.'),
    ('emp-my-plc-06888', 'Axiata Group Berhad', 'FY2025', 30, 34, 30, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'management', 'Axiata Group', 'single_period_later_than_sampling_source', 'Latest accessible integrated report used for gender facts. Selected operating-company benefits were not treated as group-wide policy evidence.'),
    ('emp-my-plc-01818', 'Bursa Malaysia Berhad', 'FY2024', 48.31, 43.90, 36.40, NULL, NULL, NULL, NULL, NULL, 98, TRUE, NULL, NULL, 'verified_positive_signals', 'senior management', 'Bursa Malaysia', 'single_period', 'Official FY2024 sustainability report: workforce, senior management and board gender; 98-day maternity and flexible work.'),
    ('emp-my-plc-06947', 'CelcomDigi Berhad', 'FY2024', NULL, 37, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'management', 'CelcomDigi', 'single_period', 'Only one gender field was verified, so the gender pillar remains null under the complete-component rule.'),
    ('emp-my-plc-01023', 'CIMB Group Holdings Berhad', 'FY2025', 57, 40, 45, NULL, NULL, NULL, NULL, NULL, 180, TRUE, TRUE, TRUE, 'complete_disclosure_for_scored_signals', 'management', 'CIMB Group', 'single_period_later_than_sampling_source', 'Maternity, paternity, hybrid/flexible work and nursing/childcare support are explicitly disclosed.'),
    ('emp-my-plc-07148', 'Duopharma Biotech Berhad', 'FY2024', 43.08, 60, 36, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, 'known_positive_signals_only', 'management category', 'Duopharma Biotech group', 'single_period', 'Women employees calculated from disclosed category counts: 843 of 1,957. Leave is mentioned without days, so no maternity points were assigned.'),
    ('emp-my-plc-05168', 'Hartalega Holdings Berhad', 'FY2024', 16, 38, 30, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, NULL, 'known_positive_signals_only', 'senior managers and managers', 'Hartalega group', 'single_period', 'Annual report copy is on a listed-company document mirror; official-host confirmation is queued. Leave days were not used.'),
    ('emp-my-plc-05819', 'Hong Leong Bank Berhad', 'FY2024', 63.99, 41.9, 33, NULL, NULL, NULL, NULL, NULL, 120, NULL, NULL, FALSE, 'known_positive_signals_plus_explicit_nonqualifier', 'senior management', 'HLB and HLISB', 'single_period', 'Women employee and management shares are calculated from disclosed HLB+HLISB counts. Five working days paternity was recorded as not exceeding the D7 statutory benchmark.'),
    ('emp-my-plc-05183', 'PETRONAS Chemicals Group Berhad', 'FY2024', 21.1, 30, 37.5, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, 'known_positive_signals_only', 'management', 'PCG group', 'single_period', 'Flexible work is scored. Comprehensive leave language without day-level duration is not converted to maternity or paternity points.'),
    ('emp-my-plc-05681', 'PETRONAS Dagangan Berhad', 'FY2024', NULL, 34, 33, NULL, NULL, NULL, NULL, NULL, 98, TRUE, TRUE, FALSE, 'verified_positive_signals', 'management', 'PETRONAS Dagangan', 'single_period', 'Overall workforce share was not located; policy evidence includes statutory maternity, flexible work and special-needs child support.'),
    ('emp-my-plc-06031', 'PETRONAS Gas Berhad', 'FY2024', 12.69, 19, 38, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, 'known_positive_signals_only', 'senior management', 'PGB group', 'single_period', 'Women employees calculated from 237 of 1,868. Flexible work is scored; unknown policy fields remain null.'),
    ('emp-my-plc-08869', 'Press Metal Aluminium Holdings Berhad', 'FY2024', 12.8, 38.5, 30, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, NULL, 'verified_positive_signals', 'management', 'Press Metal group', 'single_period', 'FY2024 integrated report discloses gender shares, flexible-time allowance and lactation room.'),
    ('emp-my-plc-01066', 'RHB Bank Berhad', 'FY2024', 60, 54.04, 30, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, NULL, 'known_positive_signals_only', 'management', 'RHB Banking Group', 'single_period', 'Management share uses the report''s management category; senior management is separately reported and queued for reviewer agreement.'),
    ('emp-my-plc-05285', 'SD Guthrie Berhad', 'FY2024', 19.5, NULL, 33, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, 'known_positive_signals_only', NULL, 'SD Guthrie group', 'single_period', 'An executive-category ratio was not treated as management. With a missing management field, the gender pillar remains null.'),
    ('emp-my-plc-04197', 'Sime Darby Berhad', 'FY2024', 25, 25, 25, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'senior management', 'Sime Darby group', 'single_period', 'FY2024 annual report gender disclosures located; no scoreable D7 policy fact located in the indexed report review.'),
    ('emp-my-plc-05211', 'Sunway Berhad', 'FY2025', 60, 65, 50, NULL, TRUE, NULL, NULL, NULL, NULL, TRUE, TRUE, NULL, 'verified_positive_signals', 'all management positions', 'Sunway group', 'single_period_later_than_sampling_source', 'FY2025 report p.95 provides gender facts; official recognition and FY2024 family-support evidence are retained with explicit period note.'),
    ('emp-my-plc-04863', 'Telekom Malaysia Berhad', 'FY2023/FY2024', 40, 35, 27.27, NULL, NULL, NULL, NULL, NULL, 98, TRUE, TRUE, FALSE, 'known_positive_signals_plus_explicit_nonqualifier', 'management', 'TM group', 'mixed_period_review_required', 'Women employees is from FY2023; management, board and policies are FY2024. Score is provisional until a reviewer resolves period consistency.'),
    ('emp-my-plc-05347', 'Tenaga Nasional Berhad', 'FY2024', 22, 25, 33, NULL, NULL, NULL, NULL, NULL, 98, TRUE, TRUE, FALSE, 'known_positive_signals_plus_explicit_nonqualifier', 'management', 'TNB group', 'single_period', 'Seven-day paternity leave is recorded as not beyond the D7 statutory benchmark; no extra points assigned.'),
