-- ReRouteHer D1-D8 full PostgreSQL import
-- Generated from the verified Iteration 1 CSVs by build_postgresql_full_import.py.
-- Release date: 2026-08-23
-- Rows upserted: 673
--
-- Compatibility mode: no pgvector extension required; embeddings use double precision[384].
-- Recommended command:
--   psql -v ON_ERROR_STOP=1 -d YOUR_DATABASE -f ReRouteHer_D1_D8_Full_PostgreSQL_Import_NoPgvector.sql
--
-- Safety: this script does not DROP schemas or tables. It creates missing objects and
-- upserts release rows inside one transaction. Rows not present in the release are not deleted.


BEGIN;

CREATE SCHEMA IF NOT EXISTS rerouteher;
SET LOCAL search_path TO rerouteher, public;
SET LOCAL standard_conforming_strings = on;

CREATE TABLE IF NOT EXISTS roles (
    role_id text PRIMARY KEY,
    role_title text NOT NULL,
    masco_code char(4) NOT NULL,
    task_summary text NOT NULL,
    remote_possibility text NOT NULL CHECK (remote_possibility IN ('low','medium','high')),
    ai_exposure text NOT NULL CHECK (ai_exposure IN ('low','medium','high')),
    flexible_role boolean NOT NULL,
    role_embedding double precision[] NOT NULL CHECK (array_length(role_embedding, 1) = 384)
);

CREATE TABLE IF NOT EXISTS skill_taxonomy (
    skill_id text PRIMARY KEY,
    canonical_name text NOT NULL,
    definition text,
    aliases text,
    skill_type text NOT NULL CHECK (skill_type IN ('technical','soft','digital')),
    competence_area text,
    level text,
    source_element_id text,
    embedding double precision[] NOT NULL CHECK (array_length(embedding, 1) = 384)
);

CREATE TABLE IF NOT EXISTS role_skills (
    role_id text NOT NULL REFERENCES roles(role_id) ON UPDATE CASCADE ON DELETE CASCADE,
    skill_id text NOT NULL REFERENCES skill_taxonomy(skill_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    skill_name text NOT NULL,
    skill_type text NOT NULL CHECK (skill_type IN ('technical','soft','digital')),
    importance numeric(5,1) NOT NULL CHECK (importance BETWEEN 0 AND 100),
    PRIMARY KEY (role_id, skill_id)
);

CREATE TABLE IF NOT EXISTS caregiving_map (
    break_activity text NOT NULL,
    onet_element_id text NOT NULL,
    onet_element_name text NOT NULL,
    onet_domain text,
    reframed_label text NOT NULL,
    source_url text,
    review_status text,
    PRIMARY KEY (break_activity, onet_element_id)
);

CREATE TABLE IF NOT EXISTS employers (
    employer_id text PRIMARY KEY,
    name text NOT NULL,
    sector text NOT NULL,
    recognition_score numeric(5,1) NOT NULL CHECK (recognition_score BETWEEN 0 AND 100),
    gender_equity_score numeric(5,1) NOT NULL CHECK (gender_equity_score BETWEEN 0 AND 100),
    policy_flex_score numeric(5,1) NOT NULL CHECK (policy_flex_score BETWEEN 0 AND 100),
    mother_friendly_score numeric(5,1) NOT NULL CHECK (mother_friendly_score BETWEEN 0 AND 100),
    confidence text NOT NULL CHECK (confidence IN ('High','Moderate','Low')),
    evidence_refs text NOT NULL
);

CREATE TABLE IF NOT EXISTS employer_sampling_context (
    employer_id text PRIMARY KEY REFERENCES employers(employer_id) ON UPDATE CASCADE ON DELETE CASCADE,
    stock_code text NOT NULL,
    name text NOT NULL,
    sector text NOT NULL,
    esg_band text,
    ftse4good_bursa_malaysia boolean,
    shariah_index boolean
);

CREATE TABLE IF NOT EXISTS employer_extractions (
    employer_id text PRIMARY KEY REFERENCES employers(employer_id) ON UPDATE CASCADE ON DELETE CASCADE,
    name text NOT NULL,
    source_period text,
    women_employees_pct numeric(6,2) CHECK (women_employees_pct BETWEEN 0 AND 100),
    women_management_pct numeric(6,2) CHECK (women_management_pct BETWEEN 0 AND 100),
    women_board_pct numeric(6,2) CHECK (women_board_pct BETWEEN 0 AND 100),
    lifeatwork_women_family_winner boolean,
    lifeatwork_other_dei_winner boolean,
    lifeatwork_finalist_or_entrant boolean,
    flexworklife_fwa_adopter boolean,
    other_gov_family_recognition boolean,
    maternity_days integer CHECK (maternity_days IS NULL OR maternity_days >= 0),
    flexible_or_remote boolean,
    childcare_nursing_phased_return boolean,
    paternity_beyond_statutory boolean,
    policy_score_basis text,
    management_definition text,
    source_scope text,
    period_consistency text,
    extraction_notes text
);

CREATE TABLE IF NOT EXISTS employer_evidence_log (
    evidence_id text PRIMARY KEY,
    employer_id text NOT NULL REFERENCES employers(employer_id) ON UPDATE CASCADE ON DELETE CASCADE,
    fact_fields text NOT NULL,
    source_title text NOT NULL,
    source_year text,
    source_url text,
    local_path text,
    page_or_section text NOT NULL,
    reported_values text,
    evidence_paraphrase text NOT NULL,
    retrieval_date date NOT NULL,
    source_type text NOT NULL,
    verification_status text NOT NULL
);

CREATE TABLE IF NOT EXISTS employer_report_search (
    employer_id text PRIMARY KEY REFERENCES employers(employer_id) ON UPDATE CASCADE ON DELETE CASCADE,
    stock_code text NOT NULL,
    name text NOT NULL,
    search_date date NOT NULL,
    sustainability_search_status text NOT NULL,
    annual_report_fallback_status text NOT NULL,
    selected_source_type text NOT NULL,
    report_year text,
    report_title text NOT NULL,
    report_url text NOT NULL,
    page_or_section text NOT NULL,
    search_completion_status text NOT NULL,
    scoreable_d7_fact_located boolean NOT NULL,
    zero_score_reason text,
    notes text
);

CREATE TABLE IF NOT EXISTS employer_validation_queue (
    employer_id text PRIMARY KEY REFERENCES employers(employer_id) ON UPDATE CASCADE ON DELETE CASCADE,
    name text NOT NULL,
    review_status text NOT NULL,
    reviewer text,
    review_date date,
    checks_required text NOT NULL,
    review_notes text
);

CREATE TABLE IF NOT EXISTS role_sector_map (
    role_id text NOT NULL REFERENCES roles(role_id) ON UPDATE CASCADE ON DELETE CASCADE,
    role_title text NOT NULL,
    msic_section char(1) NOT NULL,
    sector text NOT NULL,
    mapping_rationale text,
    reference text,
    review_status text,
    PRIMARY KEY (role_id, msic_section)
);

CREATE INDEX IF NOT EXISTS idx_roles_masco_code ON roles(masco_code);
CREATE INDEX IF NOT EXISTS idx_role_skills_skill_id ON role_skills(skill_id);
CREATE INDEX IF NOT EXISTS idx_role_skills_skill_type ON role_skills(skill_type);
CREATE INDEX IF NOT EXISTS idx_employers_sector ON employers(sector);
CREATE INDEX IF NOT EXISTS idx_employers_score ON employers(mother_friendly_score DESC);
CREATE INDEX IF NOT EXISTS idx_evidence_employer_id ON employer_evidence_log(employer_id);
CREATE INDEX IF NOT EXISTS idx_evidence_verification_status ON employer_evidence_log(verification_status);
CREATE INDEX IF NOT EXISTS idx_role_sector_sector ON role_sector_map(sector);

COMMENT ON SCHEMA rerouteher IS 'ReRouteHer Iteration 1 production data for tasks D1-D8.';
COMMENT ON TABLE role_skills IS 'Shared D2/D5 table: technical/soft rows belong to D2; digital rows belong to D5.';
COMMENT ON TABLE caregiving_map IS 'D3 standalone O*NET reframing map; onet_element_id is not a D6 skill_id foreign key.';
COMMENT ON TABLE employers IS 'D7 production employer scores; evidence and human-review status are retained in child tables.';
COMMENT ON TABLE role_sector_map IS 'D8 role-to-MSIC mapping. sector-to-employer matching is logical and is not an enforced foreign key.';

CREATE OR REPLACE VIEW role_skills_with_task AS
SELECT
    rs.role_id,
    r.role_title,
    rs.skill_id,
    st.canonical_name,
    rs.skill_name,
    rs.skill_type,
    rs.importance,
    CASE WHEN rs.skill_type = 'digital' THEN 'D5' ELSE 'D2' END AS source_task
FROM role_skills rs
JOIN roles r ON r.role_id = rs.role_id
JOIN skill_taxonomy st ON st.skill_id = rs.skill_id;

CREATE OR REPLACE VIEW employer_profiles AS
SELECT
    e.*,
    sc.stock_code,
    sc.esg_band,
    sc.ftse4good_bursa_malaysia,
    sc.shariah_index,
    ex.source_period,
    ex.women_employees_pct,
    ex.women_management_pct,
    ex.women_board_pct,
    ex.maternity_days,
    ex.flexible_or_remote,
    ex.childcare_nursing_phased_return,
    ex.paternity_beyond_statutory,
    rs.selected_source_type,
    rs.report_year,
    rs.report_url,
    rs.scoreable_d7_fact_located,
    vq.review_status AS human_review_status
FROM employers e
LEFT JOIN employer_sampling_context sc USING (employer_id)
LEFT JOIN employer_extractions ex USING (employer_id)
LEFT JOIN employer_report_search rs USING (employer_id)
LEFT JOIN employer_validation_queue vq USING (employer_id);

